analog('s-five-2','Исследовать Σₙ≥1cos(nx)/n³ на ℝ.',[S('|cos(nx)/n³|≤1/n³.','|cos t|≤1.'),S('Σ1/n³ сходится.','Для обобщённого гармонического ряда показатель p=3 больше 1.'),S('Супремум модуля хвоста ≤Σ хвостовых 1/n³.','Неравенство треугольника, затем супремум по x.'),S('Сходимость абсолютная и равномерная.','Числовой хвост стремится к нулю независимо от x.')],'Признак Вейерштрасса');
analog('s-higher-1','f=(x²+2y²)². Найти ∇f(x,y)·(x,y).',[S('f(tx,ty)=t⁴f(x,y).','Каждая внутренняя степень даёт t², затем берётся квадрат.'),S('f дифференцируема на ℝ².','Это многочлен.'),S('Дифференцируем f(tx,ty)=t⁴f(x,y) по t.','Правило цепочки применимо при фиксированных x,y.'),S('При t=1 получаем ∇f(x,y)·(x,y)=4f(x,y).','Подстановка в равенство производных даёт тождество Эйлера.')],'4f(x,y)');
analog('s-smooth-2','Найти max xy при x²+y²=2.',[S('2xy≤x²+y²=2.','Из (x−y)²≥0.'),S('xy≤1.','Деление на положительное число 2.'),S('(1,1) принадлежит окружности и даёт xy=1.','Подстановка проверяет ограничение и значение функции.'),S('Максимум равен 1.','Полученная верхняя грань достигается.')],'1');
analog('s-measure-2','Aₙ=[n,+∞). Сравнить μ(∩Aₙ) и lim μ(Aₙ).',[S('Aₙ убывают.','[n+1,+∞)⊆[n,+∞).'),S('Пересечение пусто.','Для каждого конечного x есть n>x.'),S('Мера пересечения 0, а мера каждого Aₙ бесконечна.','Мера пустого множества нулевая; луч неограниченно длинный.'),S('Равенство непрерывности сверху здесь неприменимо.','Не выполнено условие конечности хотя бы одного члена.')],'0≠+∞');
analog('s-lebesgue-1','fₙ(x)=n e⁻ⁿˣ на (0,+∞). Вычислить интегралы и поточечный предел.',[S('При x>0 функция стремится к 0.','Экспоненциальное убывание сильнее линейного роста n.'),S('∫₀ᴿn e⁻ⁿˣdx=1−e⁻ⁿᴿ.','Первообразная −e⁻ⁿˣ.'),S('Интеграл по (0,+∞) равен 1 при каждом n.','Предел при R→∞.'),S('Предел интегралов 1 не совпадает с интегралом предела 0.','Поточечной сходимости без дополнительных условий недостаточно.')],'Масса 1 при поточечном пределе 0');
analog('s-lebesgue-2','Для x∈(0,1) исследовать ∫₀¹xⁿ/(1+xⁿ)dx при n→∞.',[S('xⁿ→0 при 0<x<1.','Геометрическая последовательность с основанием меньше 1.'),S('0≤xⁿ/(1+xⁿ)≤1.','Числитель не больше знаменателя.'),S('Мажоранта 1 принадлежит L¹(0,1).','Её интеграл конечен.'),S('Предел интегралов 0.','Применена теорема Лебега о мажорируемой сходимости.')],'0');
analog('s-multiple-2','Φ(x,y)=(3x,y). Найти площадь образа единичного квадрата.',[S('DΦ=diag(3,1).','Частные производные линейного отображения.'),S('det DΦ=3≠0.','Отображение невырождено и глобально обратимо.'),S('Площадь образа равна ∫квадрат|3|dxdy.','Формула замены переменных применима к диффеоморфизму.'),S('Площадь равна 3.','Площадь исходного квадрата единица.')],'3');
analog('s-parameters-2','Вычислить Γ(6)/Γ(3).',[S('Аргументы положительны.','Допустима рекурсия гамма-функции.'),S('Γ(6)=5Γ(5)=5·4Γ(4).','Дважды применено Γ(s+1)=sΓ(s).'),S('Γ(4)=3Γ(3).','Ещё одно применение рекурсии.'),S('Отношение равно 5·4·3=60.','Γ(3)>0, поэтому общий множитель сокращается.')],'60');
analog('s-forms-2','Вычислить ∫γ(y dx+x dy) от (0,0) до (2,1).',[S('F(x,y)=xy.','Произведение имеет подходящие частные производные.'),S('dF=y dx+x dy.','Полный дифференциал вычислен явно.'),S('Интеграл равен F(2,1)−F(0,0).','Ньютон — Лейбниц для точной формы.'),S('Результат равен 2.','Подстановка концов; выбор пути не влияет.')],'2');
analog('s-six-1','Найти ∮∂D x dy для единичного квадрата с положительной ориентацией.',[S('P=0, Q=x.','Выделены коэффициенты формы.'),S('Qₓ−Pᵧ=1.','Производные равны 1 и 0.'),S('∮∂D x dy=∫_D1 dxdy.','Грин применим к гладкой форме и положительно ориентированной границе квадрата.'),S('Интеграл равен 1.','Это площадь единичного квадрата.')],'1');
analog('s-fourier-1','Найти c₀ для f(x)=2+cos(3x) на [−π,π].',[S('c₀=(1/(2π))∫₋π^πf.','Определение коэффициента при k=0.'),S('Интеграл косинуса равен 0.','Первообразная sin(3x)/3 равна нулю на обоих концах.'),S('Интеграл постоянного слагаемого равен 4π.','Длина промежутка 2π умножается на 2.'),S('c₀=2.','Деление на нормировочный множитель 2π.')],'2');
